import csv, re
from decimal import Decimal, ROUND_HALF_UP

base = "/tmp/psz-work/calib2/t5h_invoices/stock/3/"
invoices = {}
with open(base + "invoices.csv", newline="") as f:
    for row in csv.DictReader(f):
        invoices[row["invoice"].strip()] = Decimal(row["amount"].strip())

outstanding = dict(invoices)  # remaining amount per invoice
by_num = {int(k.split("-")[1]): k for k in invoices}

with open(base + "payments.csv", newline="") as f:
    for row in csv.DictReader(f):
        amount = Decimal(row["amount"].strip())
        nums = [int(n) for n in re.findall(r"\d+", row["reference"])]
        targets = [by_num[n] for n in nums if n in by_num]
        # de-duplicate while keeping order
        seen = []
        for t in targets:
            if t not in seen:
                seen.append(t)
        remaining = amount
        for inv in seen:
            if remaining <= 0:
                break
            pay = min(remaining, outstanding[inv])
            if pay > 0:
                outstanding[inv] -= pay
                remaining -= pay
        if seen and remaining > 0:
            # overpayment on the last named invoice is not carried; nothing further
            pass

out = []
for inv in sorted(invoices):
    if outstanding[inv] > 0:
        out.append((inv, outstanding[inv].quantize(Decimal("0.01"), ROUND_HALF_UP)))

with open(base + "open.csv", "w", newline="") as f:
    w = csv.writer(f, lineterminator="\n")
    w.writerow(["invoice", "outstanding"])
    for inv, amt in out:
        w.writerow([inv, f"{amt:.2f}"])
print(open(base + "open.csv").read())

